<?php $pageTitle='Add Category'; require_once __DIR__.'/includes/header.php'; $pdo=db(); $id=(int)($_GET['id']??0);$editing=$id>0;$cat=['name'=>'','slug'=>'','description'=>'','status'=>'active'];$errors=[];if($editing){$st=$pdo->prepare('SELECT * FROM blog_categories WHERE id=?');$st->execute([$id]);$cat=$st->fetch();if(!$cat)redirect('categories.php');$pageTitle='Edit Category';}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$cat=['name'=>trim($_POST['name']??''),'slug'=>trim($_POST['slug']??''),'description'=>trim($_POST['description']??''),'status'=>in_array($_POST['status']??'active',['active','inactive'],true)?$_POST['status']:'active'];if(!$cat['name'])$errors[]='Category name is required.';if(!$errors){$slug=unique_slug('blog_categories',slugify($cat['slug']?:$cat['name']),$editing?$id:null);if($editing){$pdo->prepare('UPDATE blog_categories SET name=?,slug=?,description=?,status=? WHERE id=?')->execute([$cat['name'],$slug,$cat['description'],$cat['status'],$id]);flash('success','Category updated successfully.');}else{$pdo->prepare('INSERT INTO blog_categories(name,slug,description,status) VALUES(?,?,?,?)')->execute([$cat['name'],$slug,$cat['description'],$cat['status']]);flash('success','Category created successfully.');}redirect('categories.php');}}?>
<?php if($errors): ?><div class="alert alert-danger"><?=e(implode(' ',$errors))?></div><?php endif;?><div class="panel form-panel narrow-form"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Category Name *</label><input class="form-control mb-3" id="name" name="name" value="<?=e($cat['name'])?>" required><label>Slug</label><input class="form-control mb-3" id="slug" name="slug" value="<?=e($cat['slug'])?>"><label>Description</label><textarea class="form-control mb-3" rows="5" name="description"><?=e($cat['description'])?></textarea><label>Status</label><select class="form-select mb-4" name="status"><option value="active" <?=$cat['status']==='active'?'selected':''?>>Active</option><option value="inactive" <?=$cat['status']==='inactive'?'selected':''?>>Inactive</option></select><button class="btn btn-primary">Save Category</button> <a href="categories.php" class="btn btn-light">Cancel</a></form></div><script>document.getElementById('name')?.addEventListener('input',function(){const s=document.getElementById('slug');if(!s.dataset.edited)s.value=this.value.toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')});document.getElementById('slug')?.addEventListener('input',function(){this.dataset.edited='1'});</script>
<?php require_once __DIR__.'/includes/footer.php'; ?>
